import java.util.*;

public class Main {
    interface Bpp { Object after(String name, Object bean); }
    public static void main(String[] args) {
        List<String> log = new ArrayList<>();
        Map<String, String> definitions = new LinkedHashMap<>();
        definitions.put("userService", "UserService");
        definitions.put("orderService", "OrderService");
        log.add("1 prepareBeanFactory");
        // 2: BeanFactoryPostProcessors may add or edit definitions
        definitions.put("auditService", "AuditService");
        log.add("2 BFPP phase, definitions = " + definitions.keySet());
        // 3: BeanPostProcessors are created before ordinary beans
        List<Bpp> bpps = new ArrayList<>();
        bpps.add((n, b) -> b + "[proxy]");
        log.add("3 registerBeanPostProcessors (" + bpps.size() + ")");
        log.add("4 onRefresh (Boot starts the web server here)");
        // 5: preInstantiateSingletons creates every non-lazy singleton
        Map<String, Object> singletons = new LinkedHashMap<>();
        for (Map.Entry<String, String> d : definitions.entrySet()) {
            Object bean = d.getValue();
            for (Bpp p : bpps) bean = p.after(d.getKey(), bean);
            singletons.put(d.getKey(), bean);
            log.add("5 created " + d.getKey());
        }
        log.add("6 finishRefresh -> ContextRefreshedEvent");
        log.forEach(System.out::println);
        System.out.println(singletons);
    }
}

import java.lang.reflect.Proxy;
import java.util.*;

public class Main {
    interface Greeter { String hello(); }
    public static void main(String[] args) {
        // Bean definitions: name -> property map (what a BFPP can edit)
        Map<String, Map<String, String>> defs = new LinkedHashMap<>();
        defs.put("greeter", new HashMap<>(Map.of("text", "${greeting}")));
        System.out.println("before BFPP: " + defs);
        // BFPP: runs once, edits definitions, no bean exists yet
        Map<String, String> props = Map.of("greeting", "hello world");
        for (Map<String, String> d : defs.values())
            d.replaceAll((k, v) -> v.startsWith("${") ? props.get(v.substring(2, v.length() - 1)) : v);
        System.out.println("after BFPP:  " + defs);
        // Instantiate from the edited definition
        String text = defs.get("greeter").get("text");
        Greeter raw = () -> text;
        // BPP: runs for each instance and may return a different object (proxy)
        Greeter bean = (Greeter) Proxy.newProxyInstance(Main.class.getClassLoader(),
            new Class<?>[]{Greeter.class}, (p, m, a) -> "[logged] " + m.invoke(raw, a));
        System.out.println(bean.hello());
        System.out.println("proxy class differs from raw: " + (bean.getClass() != raw.getClass()));
    }
}

