public class Main {
    static List<String> log = new ArrayList<>();
    static class Bean {
        Bean() { log.add("constructor"); }
        void inject() { log.add("populate (setter/field injection)"); }
        void aware() { log.add("BeanNameAware / BeanFactoryAware"); }
        void postConstruct() { log.add("@PostConstruct (a BPP before-init step)"); }
        void afterPropertiesSet() { log.add("afterPropertiesSet"); }
        void initMethod() { log.add("custom init-method"); }
        void destroy() { log.add("@PreDestroy / destroy()"); }
    }
    public static void main(String[] args) {
        Bean target = new Bean();
        log.add("early reference exposed (third-level cache)");
        target.inject();
        target.aware();
        target.postConstruct();
        target.afterPropertiesSet();
        target.initMethod();
        // The proxy is made AFTER init, so init callbacks run on the raw target
        log.add("postProcessAfterInitialization -> proxy created");
        log.add("registered for destruction");
        target.destroy();
        for (int i = 0; i < log.size(); i++) System.out.println((i + 1) + ". " + log.get(i));
    }
