import java.util.*;
import java.util.function.Supplier;

public class Main {
    static Map<String, Object> singletons = new HashMap<>();        // level 1: finished
    static Map<String, Object> early = new HashMap<>();             // level 2: early refs
    static Map<String, Supplier<Object>> factories = new HashMap<>();// level 3: factories
    static Set<String> inCreation = new HashSet<>();
    static class A { B b; }
    static class B { A a; }

    static Object get(String name) {
        if (singletons.containsKey(name)) return singletons.get(name);
        if (early.containsKey(name)) return early.get(name);
        if (inCreation.contains(name) && factories.containsKey(name)) {
            Object ref = factories.remove(name).get();   // a BPP could wrap a proxy here
            early.put(name, ref);
            System.out.println("early reference of " + name + " handed out");
            return ref;
        }
        return create(name);
    }
    static Object create(String name) {
        inCreation.add(name);
        Object bean = name.equals("a") ? new A() : new B();
        factories.put(name, () -> bean);                 // expose right after instantiation
        if (bean instanceof A x) x.b = (B) get("b");     // populate triggers the other bean
        else ((B) bean).a = (A) get("a");
        factories.remove(name); early.remove(name); inCreation.remove(name);
        singletons.put(name, bean);
        return bean;
    }
    public static void main(String[] args) {
        A a = (A) get("a");
        System.out.println("a.b.a == a ? " + (a.b.a == a));
    }
}

import java.util.*;

public class Main {
    record Candidate(String name, boolean primary, int priority, String qualifier) {}
    static String pick(List<Candidate> all, String qualifier, String paramName) {
        List<Candidate> c = new ArrayList<>(all);
        if (qualifier != null) c.removeIf(x -> !qualifier.equals(x.qualifier()) && !qualifier.equals(x.name()));
        if (c.isEmpty()) return "NoSuchBeanDefinitionException";
        if (c.size() == 1) return c.get(0).name();
        List<Candidate> p = c.stream().filter(Candidate::primary).toList();      // 1. @Primary
        if (p.size() == 1) return p.get(0).name();
        Candidate best = Collections.min(c, Comparator.comparingInt(Candidate::priority)); // 2. @Priority
        if (best.priority() < Integer.MAX_VALUE) return best.name();
        for (Candidate x : c) if (x.name().equals(paramName)) return x.name();   // 3. parameter name
        return "NoUniqueBeanDefinitionException";
    }
    public static void main(String[] args) {
        int none = Integer.MAX_VALUE;
        List<Candidate> pay = List.of(new Candidate("card", false, none, null),
            new Candidate("paypal", true, none, "fast"), new Candidate("bank", false, none, null));
        System.out.println("plain, param 'bank'   -> " + pick(pay, null, "bank"));
        System.out.println("qualifier 'card'      -> " + pick(pay, "card", "bank"));
        System.out.println("qualifier 'fast'      -> " + pick(pay, "fast", "x"));
        System.out.println("no primary, param 'z' -> " + pick(List.of(pay.get(0), pay.get(2)), null, "z"));
        System.out.println("qualifier 'nope'      -> " + pick(pay, "nope", "x"));
    }
}

import java.util.*;

public class Main {
    static int created = 0;
    static class Pool { final int id = ++created; }
    static class Repo { final Pool pool; Repo(Pool p) { pool = p; } }
    static class Audit { final Pool pool; Audit(Pool p) { pool = p; } }

    // Lite mode: plain class, @Bean method calls are ordinary Java calls
    static class LiteConfig {
        Pool pool() { return new Pool(); }
        Repo repo() { return new Repo(pool()); }
        Audit audit() { return new Audit(pool()); }
    }
    // Full mode: CGLIB-style subclass caches the result, like BeanMethodInterceptor
    static class FullConfig extends LiteConfig {
        private Pool cached;
        @Override Pool pool() { if (cached == null) cached = super.pool(); return cached; }
    }
    static void run(String label, LiteConfig cfg) {
        created = 0;
        Repo r = cfg.repo(); Audit a = cfg.audit();
        System.out.println(label + ": pools created = " + created + ", shared = " + (r.pool == a.pool));
    }
    public static void main(String[] args) {
        run("lite (proxyBeanMethods=false)", new LiteConfig());
        run("full (proxyBeanMethods=true) ", new FullConfig());
    }
}

import java.lang.reflect.Proxy;
import java.util.*;

public class Main {
    interface Cart { void add(String item); List<String> items(); }
    // Stand-in for RequestContextHolder: one "request scope" per thread
    static ThreadLocal<Cart> requestScope = new ThreadLocal<>();
    static Cart newCart() {
        List<String> l = new ArrayList<>();
        return new Cart() {
            public void add(String i) { l.add(i); }
            public List<String> items() { return l; }
        };
    }
    public static void main(String[] args) {
        // The singleton holds ONE proxy; every call looks up the current request's bean
        Cart proxy = (Cart) Proxy.newProxyInstance(Main.class.getClassLoader(), new Class<?>[]{Cart.class},
            (p, m, a) -> {
                Cart target = requestScope.get();
                if (target == null) throw new IllegalStateException("Scope 'request' is not active");
                return m.invoke(target, a);
            });
        for (String user : List.of("req1", "req2")) {
            requestScope.set(newCart());            // request starts
            proxy.add(user + "-book");
            System.out.println(user + " sees " + proxy.items());
            requestScope.remove();                  // request ends
        }
        try { proxy.items(); } catch (IllegalStateException e) { System.out.println("outside request: " + e.getMessage()); }
    }
}

import java.lang.reflect.*;
import java.util.*;

public class Main {
    interface Service { String work(String in); }
    interface Advice { Object invoke(Method m, Object[] a, java.util.concurrent.Callable<Object> next) throws Exception; }
    public static void main(String[] args) {
        Service target = in -> "done(" + in + ")";
        List<Advice> chain = List.of(
            (m, a, next) -> { System.out.println("tx begin"); Object r = next.call(); System.out.println("tx commit"); return r; },
            (m, a, next) -> { System.out.println("  log before " + m.getName()); return next.call(); });
        // JDK dynamic proxy: implements the interface only, delegates to the target
        Service proxy = (Service) Proxy.newProxyInstance(Main.class.getClassLoader(), new Class<?>[]{Service.class},
            (p, m, a) -> run(chain, 0, m, a, target));
        System.out.println("proxy is Service: " + (proxy instanceof Service));
        System.out.println("result = " + proxy.work("x"));
    }
    // Each interceptor calls "proceed" (next); the last one calls the target
    static Object run(List<Advice> c, int i, Method m, Object[] a, Object t) throws Exception {
        if (i == c.size()) return m.invoke(t, a);
        return c.get(i).invoke(m, a, () -> run(c, i + 1, m, a, t));
    }
}

import java.lang.reflect.Proxy;

public class Main {
    interface Api { void outer(); void inner(); }
    static class Impl implements Api {
        Api self;                                   // injected proxy reference
        public void outer() { System.out.println("outer"); this.inner(); self.inner(); }
        public void inner() { System.out.println("inner body"); }
    }
    public static void main(String[] args) {
        Impl target = new Impl();
        // Advice stands in for @Transactional: prints when a call goes through the proxy
        Api proxy = (Api) Proxy.newProxyInstance(Main.class.getClassLoader(), new Class<?>[]{Api.class},
            (p, m, a) -> {
                if (m.getName().equals("inner")) System.out.println("  [advice] transaction for inner");
                return m.invoke(target, a);
            });
        target.self = proxy;   // option: inject the bean into itself
        System.out.println("-- call outer() through the proxy");
        proxy.outer();
        System.out.println("(first inner via this.: no advice; second via self: advice runs)");
    }
}

import java.util.*;

public class Main {
    static class Conn {
        final int id; Conn(int id) { this.id = id; }
        void commit() { System.out.println("conn" + id + " COMMIT"); }
        void rollback() { System.out.println("conn" + id + " ROLLBACK"); }
    }
    // Stand-in for TransactionSynchronizationManager: one bound connection per thread
    static ThreadLocal<Conn> bound = new ThreadLocal<>();
    static int next = 1;

    // What TransactionInterceptor does around the proxied method
    static void inTransaction(Runnable body) {
        Conn c = new Conn(next++);              // borrow connection, autoCommit(false)
        bound.set(c);
        try { body.run(); c.commit(); }
        catch (RuntimeException e) { c.rollback(); System.out.println("caught " + e.getMessage()); }
        finally { bound.remove(); }
    }
    // Stand-in for JdbcTemplate: finds the bound connection instead of taking a new one
    static void execute(String sql) {
        System.out.println("conn" + bound.get().id + ": " + sql);
    }
    public static void main(String[] args) {
        inTransaction(() -> { execute("UPDATE a"); execute("UPDATE b"); });
        inTransaction(() -> { execute("UPDATE a"); throw new IllegalStateException("boom"); });
        System.out.println("bound after: " + bound.get());
    }
}

import java.util.*;

public class Main {
    static int connections = 0, maxHeld = 0, held = 0;
    static Deque<String> stack = new ArrayDeque<>();
    static boolean rollbackOnly = false;

    static void required(Runnable body) {
        if (stack.isEmpty()) { open("T1 (new)"); body.run(); close(); }
        else { System.out.println("  join existing tx, same connection"); body.run(); }
    }
    static void requiresNew(Runnable body) {
        System.out.println("  suspend outer, open second connection");
        open("T2 (new)"); body.run(); close();
    }
    static void open(String n) { stack.push(n); connections++; held++; maxHeld = Math.max(maxHeld, held); }
    static void close() { stack.pop(); held--; }

    public static void main(String[] args) {
        System.out.println("REQUIRED inside REQUIRED:");
        required(() -> required(() -> System.out.println("  inner work")));
        System.out.println("connections used = " + connections + ", held at once = " + maxHeld);
        connections = 0; maxHeld = 0;
        System.out.println("REQUIRES_NEW inside REQUIRED:");
        required(() -> requiresNew(() -> System.out.println("  inner work")));
        System.out.println("connections used = " + connections + ", held at once = " + maxHeld);
        // A small pool of N connections with N threads each holding 2 -> everybody waits
        int pool = 10, threads = 10;
        System.out.println("pool=" + pool + ", threads=" + threads + ", needed=" + threads * maxHeld
            + (threads * maxHeld > pool ? " -> possible pool-exhaustion deadlock" : " -> ok"));
    }
}

import java.util.*;

public class Main {
    // Stand-in for TransactionSynchronizationManager callbacks
    static List<Runnable> afterCommit = new ArrayList<>();

    static void publish(String event, boolean inTx) {
        if (inTx) afterCommit.add(() -> System.out.println("  listener ran for " + event));
        else System.out.println("  no transaction: listener skipped for " + event);
    }
    static void transaction(String name, boolean fail) {
        System.out.println(name + ":");
        afterCommit.clear();
        System.out.println("  saving order");
        publish("OrderPlaced", true);          // registered, not run yet
        if (fail) { System.out.println("  ROLLBACK -> after-commit listeners dropped"); return; }
        System.out.println("  COMMIT");
        afterCommit.forEach(Runnable::run);    // only now: send email, call other service
    }
    public static void main(String[] args) {
        transaction("successful tx", false);
        transaction("failing tx   ", true);
        publish("OrderPlaced", false);
    }
}

import java.util.*;
import java.util.function.Predicate;

public class Main {
    record AutoConfig(String bean, String needsClass, Predicate<Set<String>> condition) {}
    public static void main(String[] args) {
        Set<String> classpath = Set.of("DataSource", "Jackson");     // what is on the classpath
        Set<String> registered = new LinkedHashSet<>();
        registered.add("objectMapper");                              // the USER defined this bean
        // Auto-configs are processed AFTER user configuration (deferred import)
        List<AutoConfig> candidates = List.of(
            new AutoConfig("objectMapper", "Jackson", beans -> !beans.contains("objectMapper")), // OnMissingBean
            new AutoConfig("jdbcTemplate", "DataSource", beans -> !beans.contains("jdbcTemplate")),
            new AutoConfig("kafkaTemplate", "Kafka", beans -> true));                          // OnClass fails
        for (AutoConfig c : candidates) {
            if (!classpath.contains(c.needsClass())) { System.out.println(c.bean() + ": skipped, class " + c.needsClass() + " missing"); continue; }
            if (!c.condition().test(registered)) { System.out.println(c.bean() + ": backed off, user bean exists"); continue; }
            registered.add(c.bean());
            System.out.println(c.bean() + ": auto-configured");
        }
        System.out.println("final beans: " + registered);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Ordered property sources, highest priority first
        Map<String, String> cmdLine = Map.of("server.port", "9000");
        Map<String, String> env = Map.of("SERVER_PORT", "8500", "APP_GREETING", "hi ${app.name}");
        Map<String, String> profileFile = Map.of("app.name", "demo-prod", "db.url", "jdbc:prod");
        Map<String, String> defaultFile = Map.of("server.port", "8080", "app.name", "demo", "db.url", "jdbc:dev");
        List<Map<String, String>> sources = List.of(cmdLine, env, profileFile, defaultFile);

        for (String key : List.of("server.port", "db.url", "app.greeting"))
            System.out.println(key + " = " + resolve(sources, key));
    }
    static String resolve(List<Map<String, String>> sources, String key) {
        String raw = null;
        for (Map<String, String> s : sources) {                      // first source that has the key wins
            if (s.containsKey(key)) { raw = s.get(key); break; }
            String relaxed = key.toUpperCase().replace('.', '_');    // relaxed binding: server.port -> SERVER_PORT
            if (s.containsKey(relaxed)) { raw = s.get(relaxed); break; }
        }
        if (raw == null) return null;
        int i;                                                       // then resolve ${...} placeholders
        while ((i = raw.indexOf("${")) >= 0) {
            int j = raw.indexOf('}', i);
            raw = raw.substring(0, i) + resolve(sources, raw.substring(i + 2, j)) + raw.substring(j + 1);
        }
        return raw;
    }
}
